);

CREATE INDEX IF NOT EXISTS idx_cost_logs_run_id ON cost_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_cost_logs_agent_id ON cost_logs(agent_id);
CREATE INDEX IF NOT EXISTS idx_cost_logs_model ON cost_logs(model);
CREATE INDEX IF NOT EXISTS idx_cost_logs_created_at ON cost_logs(created_at DESC);

ALTER TABLE cost_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "cost_logs_service_role_all" ON cost_logs FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE cost_logs IS 'Per-run token cost. Enables per-agent and per-pod cost trending.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS pattern_usage (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
