  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_pattern_usage_agent_id ON pattern_usage(agent_id);
CREATE INDEX IF NOT EXISTS idx_pattern_usage_pattern_file ON pattern_usage(pattern_file);
CREATE INDEX IF NOT EXISTS idx_pattern_usage_used_at ON pattern_usage(used_at DESC);

ALTER TABLE pattern_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY "pattern_usage_service_role_all" ON pattern_usage FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE pattern_usage IS 'Tracks pattern usage by agents. Used by Mira to detect knowledge decay (90 days unused → archive).';

-- ============================================================================

CREATE TABLE IF NOT EXISTS delegation_graph (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  from_agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  to_agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  task_type text NOT NULL,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  success bool NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_delegation_graph_from ON delegation_graph(from_agent_id);
CREATE INDEX IF NOT EXISTS idx_delegation_graph_to ON delegation_graph(to_agent_id);
CREATE INDEX IF NOT EXISTS idx_delegation_graph_success ON delegation_graph(success);

ALTER TABLE delegation_graph ENABLE ROW LEVEL SECURITY;
CREATE POLICY "delegation_graph_service_role_all" ON delegation_graph FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE delegation_graph IS 'Agent-to-agent task handoff. Used by Forge to detect bottlenecks (>40% delegation to one agent).';

-- ============================================================================
-- AUDIT & COMPLIANCE TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS incidents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  incident_type text NOT NULL CHECK (incident_type IN ('antipattern', 'regression', 'pip_candidate', 'promotion_candidate', 'production_bug', 'cost_breach', 'time_breach')),
  severity text NOT NULL CHECK (severity IN ('S1', 'S2', 'S3', 'S4')),
  description text NOT NULL,
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  root_cause text,
  resolved bool NOT NULL DEFAULT false,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_incidents_agent_id ON incidents(agent_id);
CREATE INDEX IF NOT EXISTS idx_incidents_severity ON incidents(severity);
CREATE INDEX IF NOT EXISTS idx_incidents_resolved ON incidents(resolved);
CREATE INDEX IF NOT EXISTS idx_incidents_type_severity ON incidents(incident_type, severity);

ALTER TABLE incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "incidents_service_role_all" ON incidents FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE incidents IS 'Witness writes incidents. S1=PIP candidate, S2=promotion candidate, S3=antipattern, S4=info.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS memory_updates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  updated_by text NOT NULL,
  file_path text NOT NULL,
  change_type text NOT NULL CHECK (change_type IN ('create', 'update', 'delete', 'archive')),
  diff_summary text,
  bytes_changed int,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_memory_updates_updated_by ON memory_updates(updated_by);
CREATE INDEX IF NOT EXISTS idx_memory_updates_file_path ON memory_updates(file_path);
CREATE INDEX IF NOT EXISTS idx_memory_updates_created_at ON memory_updates(created_at DESC);

ALTER TABLE memory_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "memory_updates_service_role_all" ON memory_updates FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE memory_updates IS 'Immutable audit log of every memory file change.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS yash_overrides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  override_type text NOT NULL,
  original_output text NOT NULL,
  corrected_output text NOT NULL,
  lesson_extracted bool NOT NULL DEFAULT false,
  lesson_summary text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_yash_overrides_agent_id ON yash_overrides(agent_id);
CREATE INDEX IF NOT EXISTS idx_yash_overrides_lesson_extracted ON yash_overrides(lesson_extracted) WHERE lesson_extracted = false;
CREATE INDEX IF NOT EXISTS idx_yash_overrides_created_at ON yash_overrides(created_at DESC);

ALTER TABLE yash_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY "yash_overrides_service_role_all" ON yash_overrides FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE yash_overrides IS 'P0 highest-priority signal: Yash corrections feed Tutor immediately.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS capability_gaps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  detected_by text NOT NULL,
  description text NOT NULL,
  required_skills text[] NOT NULL,
  proposed_agent text,
  status text NOT NULL DEFAULT 'detected' CHECK (status IN ('detected', 'approved', 'building', 'deployed', 'rejected')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_capability_gaps_status ON capability_gaps(status);
CREATE INDEX IF NOT EXISTS idx_capability_gaps_required_skills ON capability_gaps USING GIN(required_skills);

ALTER TABLE capability_gaps ENABLE ROW LEVEL SECURITY;
CREATE POLICY "capability_gaps_service_role_all" ON capability_gaps FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE capability_gaps IS 'Roster detects, Forge proposes new agents for. Status flow: detected → approved → building → deployed.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS proposed_patterns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  detected_by text NOT NULL,
  pattern_type text NOT NULL CHECK (pattern_type IN ('good', 'avoid', 'optimization', 'security', 'performance')),
  title text NOT NULL,
  content text NOT NULL,
  evidence jsonb NOT NULL,
  signature text,
  status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'approved', 'rejected')),
  reviewed_at timestamptz,
  reviewed_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_proposed_patterns_status ON proposed_patterns(status);
CREATE INDEX IF NOT EXISTS idx_proposed_patterns_pattern_type ON proposed_patterns(pattern_type);
CREATE INDEX IF NOT EXISTS idx_proposed_patterns_signature ON proposed_patterns(signature) WHERE signature IS NOT NULL;

ALTER TABLE proposed_patterns ENABLE ROW LEVEL SECURITY;
CREATE POLICY "proposed_patterns_service_role_all" ON proposed_patterns FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE proposed_patterns IS 'Mira proposes patterns; Yash approves. Witness reads approved avoid patterns to detect antipatterns.';

-- ============================================================================
-- EVENT BUS TABLE
-- ============================================================================

CREATE TABLE IF NOT EXISTS agent_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_agent_events_agent_id ON agent_events(agent_id);
CREATE INDEX IF NOT EXISTS idx_agent_events_run_id ON agent_events(run_id);
CREATE INDEX IF NOT EXISTS idx_agent_events_event_type ON agent_events(event_type);
CREATE INDEX IF NOT EXISTS idx_agent_events_created_at ON agent_events(created_at DESC);

ALTER TABLE agent_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "agent_events_service_role_all" ON agent_events FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE agent_events IS 'Append-only event stream for real-time observability. Cadence/Witness/Tutor subscribe via Realtime.';

-- ============================================================================
-- HELPER FUNCTIONS
-- ============================================================================

CREATE OR REPLACE FUNCTION compute_composite_score(
  p_gate_pass_rate numeric,
  p_first_try_success numeric,
  p_rework_cycles numeric,
  p_yash_override_rate numeric
) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$
  SELECT (
    (COALESCE(p_gate_pass_rate, 0) * 0.40) +
    (COALESCE(p_first_try_success, 0) * 0.30) +
    ((100 - COALESCE(p_rework_cycles, 0)) * 0.20 / 100) +
    ((100 - COALESCE(p_yash_override_rate, 0)) * 0.10 / 100)
  )::numeric(5, 2);
$$;
COMMENT ON FUNCTION compute_composite_score IS 'Weighted composite: gate 40 + first_try 30 + rework 20 + yash_override 10.';

CREATE OR REPLACE FUNCTION get_agent_peer_avg(
  p_agent_id uuid,
  p_days int DEFAULT 14
) RETURNS numeric LANGUAGE sql STABLE AS $$
  SELECT COALESCE(AVG(ar.composite_score), 0)::numeric(5, 2)
  FROM agent_runs ar
  JOIN agents a ON ar.agent_id = a.id
  WHERE a.level = (SELECT level FROM agents WHERE id = p_agent_id)
    AND ar.created_at >= NOW() - (p_days || ' days')::interval
    AND ar.agent_id != p_agent_id
    AND ar.classification = 'SUCCESS';
$$;
COMMENT ON FUNCTION get_agent_peer_avg IS 'Avg composite score of same-level peers, last N days (default 14).';

CREATE OR REPLACE FUNCTION should_promote(p_agent_id uuid)
RETURNS bool LANGUAGE sql STABLE AS $$
  SELECT (
    (SELECT AVG(composite_score) FROM agent_runs
       WHERE agent_id = p_agent_id
         AND created_at >= NOW() - interval '14 days'
         AND classification = 'SUCCESS') > get_agent_peer_avg(p_agent_id, 14)
  )
  AND (
    (SELECT COUNT(*) FROM agent_runs
       WHERE agent_id = p_agent_id
         AND created_at >= NOW() - interval '14 days') >= 5
  )
  AND NOT EXISTS (
    SELECT 1 FROM pip_records WHERE agent_id = p_agent_id AND status = 'active'
  )
  AND NOT EXISTS (
    SELECT 1 FROM yash_overrides
      WHERE agent_id = p_agent_id AND created_at >= NOW() - interval '7 days'
  )
  AND NOT EXISTS (
    SELECT 1 FROM agent_runs
      WHERE agent_id = p_agent_id
        AND classification = 'ANTIPATTERN'
        AND created_at >= NOW() - interval '30 days'
  );
$$;
COMMENT ON FUNCTION should_promote IS 'Returns true if agent meets ALL 5 promotion criteria. Cadence still requires Yash sign-off.';

CREATE OR REPLACE FUNCTION should_open_pip(p_agent_id uuid)
RETURNS bool LANGUAGE sql STABLE AS $$
  SELECT (
    (SELECT
       COUNT(*) FILTER (WHERE classification = 'SUCCESS')::numeric
         / NULLIF(COUNT(*), 0)
       FROM (
         SELECT classification FROM agent_runs
           WHERE agent_id = p_agent_id
           ORDER BY created_at DESC LIMIT 20
       ) recent
    ) < 0.70
  )
  OR (
    (SELECT COUNT(*) FROM agent_runs
       WHERE agent_id = p_agent_id
         AND classification = 'ANTIPATTERN'
         AND created_at >= NOW() - interval '30 days') >= 3
  )
  OR EXISTS (
    SELECT 1 FROM yash_overrides
      WHERE agent_id = p_agent_id
        AND created_at >= NOW() - interval '14 days'
        AND lesson_summary IS NOT NULL
  );
$$;
COMMENT ON FUNCTION should_open_pip IS 'Returns true if agent triggers ANY PIP threshold: <70% success in last 20 runs, OR 3+ antipatterns in 30d, OR Yash override with lesson in 14d.';

-- ============================================================================
-- TRIGGERS
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_compute_run_composite_score()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  gate_rate numeric;
  first_try numeric;
  rework numeric;
  override_rate numeric;
BEGIN
  gate_rate := CASE
    WHEN (NEW.gates_passed + NEW.gates_failed) = 0 THEN 100
    ELSE (NEW.gates_passed::numeric / (NEW.gates_passed + NEW.gates_failed)::numeric) * 100
  END;
  first_try := CASE WHEN NEW.first_try_success THEN 100 ELSE 0 END;
  rework := LEAST(NEW.retries * 20, 100);
  override_rate := CASE WHEN NEW.yash_override THEN 100 ELSE 0 END;
  NEW.composite_score := compute_composite_score(gate_rate, first_try, rework, override_rate);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trig_agent_runs_compute_score ON agent_runs;
CREATE TRIGGER trig_agent_runs_compute_score
BEFORE INSERT ON agent_runs
FOR EACH ROW EXECUTE FUNCTION fn_compute_run_composite_score();

-- ----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION fn_update_agent_stats()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  total_runs int;
  success_count int;
  avg_score numeric;
  total_cost numeric;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE classification = 'SUCCESS'),
    AVG(composite_score),
    SUM(cost_usd)
  INTO total_runs, success_count, avg_score, total_cost
  FROM agent_runs
  WHERE agent_id = NEW.agent_id;

  UPDATE agents
  SET stats = jsonb_build_object(
    'run_count', total_runs,
    'success_rate', ROUND(success_count::numeric / NULLIF(total_runs, 0), 2),
    'avg_composite_score', ROUND(COALESCE(avg_score, 0), 2),
    'total_cost_usd', ROUND(COALESCE(total_cost, 0), 4),
    'last_run_at', NEW.created_at
  ),
  updated_at = NOW()
  WHERE id = NEW.agent_id;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trig_agent_runs_update_stats ON agent_runs;
CREATE TRIGGER trig_agent_runs_update_stats
AFTER INSERT ON agent_runs
FOR EACH ROW EXECUTE FUNCTION fn_update_agent_stats();

-- ----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION fn_update_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trig_agents_updated_at ON agents;
CREATE TRIGGER trig_agents_updated_at BEFORE UPDATE ON agents FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_agent_runs_updated_at ON agent_runs;
CREATE TRIGGER trig_agent_runs_updated_at BEFORE UPDATE ON agent_runs FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_agent_reviews_updated_at ON agent_reviews;
CREATE TRIGGER trig_agent_reviews_updated_at BEFORE UPDATE ON agent_reviews FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_pip_records_updated_at ON pip_records;
CREATE TRIGGER trig_pip_records_updated_at BEFORE UPDATE ON pip_records FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_training_cycles_updated_at ON training_cycles;
CREATE TRIGGER trig_training_cycles_updated_at BEFORE UPDATE ON training_cycles FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_training_patches_updated_at ON training_patches;
CREATE TRIGGER trig_training_patches_updated_at BEFORE UPDATE ON training_patches FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_training_requests_updated_at ON training_requests;
CREATE TRIGGER trig_training_requests_updated_at BEFORE UPDATE ON training_requests FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_delegation_graph_updated_at ON delegation_graph;
CREATE TRIGGER trig_delegation_graph_updated_at BEFORE UPDATE ON delegation_graph FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_incidents_updated_at ON incidents;
CREATE TRIGGER trig_incidents_updated_at BEFORE UPDATE ON incidents FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_yash_overrides_updated_at ON yash_overrides;
CREATE TRIGGER trig_yash_overrides_updated_at BEFORE UPDATE ON yash_overrides FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_proposed_patterns_updated_at ON proposed_patterns;
CREATE TRIGGER trig_proposed_patterns_updated_at BEFORE UPDATE ON proposed_patterns FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();
DROP TRIGGER IF EXISTS trig_capability_gaps_updated_at ON capability_gaps;
CREATE TRIGGER trig_capability_gaps_updated_at BEFORE UPDATE ON capability_gaps FOR EACH ROW EXECUTE FUNCTION fn_update_updated_at();

-- ============================================================================
-- VIEWS
-- ============================================================================

CREATE OR REPLACE VIEW agent_leaderboard AS
SELECT
  a.id, a.name, a.title, a.level_title, a.department, a.pod, a.status,
  COALESCE((a.stats ->> 'run_count')::int, 0) as run_count,
  COALESCE((a.stats ->> 'success_rate')::numeric, 0) as success_rate,
  COALESCE((a.stats ->> 'avg_composite_score')::numeric, 0) as composite_score,
  COALESCE((a.stats ->> 'total_cost_usd')::numeric, 0) as total_cost_usd,
  (a.stats ->> 'last_run_at')::timestamptz as last_run_at,
  RANK() OVER (ORDER BY COALESCE((a.stats ->> 'avg_composite_score')::numeric, 0) DESC) as rank
FROM agents a
WHERE a.status IN ('deployed', 'training');

COMMENT ON VIEW agent_leaderboard IS 'Live leaderboard for Cadence weekly review.';

CREATE OR REPLACE VIEW recent_activity AS
SELECT
  ae.id, ae.agent_id, a.name as agent_name, ae.event_type, ae.payload,
  ar.run_id, ar.classification, ar.composite_score, ae.created_at
FROM agent_events ae
LEFT JOIN agents a ON ae.agent_id = a.id
LEFT JOIN agent_runs ar ON ae.run_id = ar.id
ORDER BY ae.created_at DESC
LIMIT 200;

COMMENT ON VIEW recent_activity IS 'Last 200 events across all agents — for Witness daily sweep + ad-hoc debug.';

CREATE OR REPLACE VIEW pod_health AS
SELECT
  COALESCE(pod, 'unassigned') as pod,
  COUNT(*) as agent_count,
  AVG(COALESCE((stats ->> 'avg_composite_score')::numeric, 0))::numeric(5, 2) as avg_pod_score,
  AVG(COALESCE((stats ->> 'success_rate')::numeric, 0))::numeric(5, 2) as avg_pod_success_rate,
  SUM(COALESCE((stats ->> 'total_cost_usd')::numeric, 0))::numeric(10, 2) as total_pod_cost
FROM agents
WHERE status IN ('deployed', 'training')
GROUP BY pod
ORDER BY avg_pod_score DESC;

COMMENT ON VIEW pod_health IS 'Per-pod health for stack-pod monitoring (Pod A, B, C). Used by Cadence + Rex.';

