-- ============================================================================
-- Boldteq Agent-Ops Initial Schema
-- Migration: 20260418000001_agent_ops_initial.sql
-- Purpose:   Full agent-ops database for HR & performance tracking
-- Plan:      ~/.claude/plans/hr-team-agent-can-melodic-dolphin.md
