-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ============================================================================
-- CORE TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  title text NOT NULL,
  department text NOT NULL,
  phase text,
  level int NOT NULL DEFAULT 2 CHECK (level BETWEEN 1 AND 4),
  level_title text GENERATED ALWAYS AS (
    CASE level
      WHEN 1 THEN 'Probation'
      WHEN 2 THEN 'Active'
      WHEN 3 THEN 'Expert'
      WHEN 4 THEN 'Architect'
      ELSE 'Unknown'
    END
  ) STORED,
  status text NOT NULL DEFAULT 'deployed' CHECK (status IN ('provisioned', 'deployed', 'training', 'pip', 'retired')),
  reports_to uuid REFERENCES agents(id) ON DELETE SET NULL,
  pod text,
  stack_assignment text,
  skills jsonb NOT NULL DEFAULT '[]'::jsonb,
  stats jsonb NOT NULL DEFAULT '{
    "run_count": 0,
    "success_rate": 0.0,
    "avg_composite_score": 0.0,
    "total_cost_usd": 0.0,
    "last_run_at": null
  }'::jsonb,
  experience_points int NOT NULL DEFAULT 0,
  hired_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_agents_name ON agents(name);
CREATE INDEX IF NOT EXISTS idx_agents_level ON agents(level);
CREATE INDEX IF NOT EXISTS idx_agents_status ON agents(status) WHERE status IN ('deployed', 'training');
CREATE INDEX IF NOT EXISTS idx_agents_department ON agents(department);
CREATE INDEX IF NOT EXISTS idx_agents_reports_to ON agents(reports_to);
CREATE INDEX IF NOT EXISTS idx_agents_pod ON agents(pod) WHERE pod IS NOT NULL;

ALTER TABLE agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "agents_service_role_all" ON agents FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE agents IS 'Agent identity, role, level, pod assignment, running stats. Replaces registry.json.';
COMMENT ON COLUMN agents.pod IS 'Pod assignment for stack-specific engineers: pod-a (Next.js), pod-b (Shopify Native), pod-c (Shopify External). NULL for non-pod agents.';
COMMENT ON COLUMN agents.stack_assignment IS 'Specific stack: nextjs-supabase-railway, shopify-native, shopify-external, multi (deprecated for new agents).';

-- ============================================================================

CREATE TABLE IF NOT EXISTS agent_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  run_id text NOT NULL UNIQUE,
  task_type text NOT NULL,
  classification text NOT NULL CHECK (classification IN ('SUCCESS', 'PARTIAL', 'FAILURE', 'TIMEOUT', 'REGRESSION', 'ANTIPATTERN', 'ESCALATED')),
  duration_ms int NOT NULL,
  token_count int,
  cost_usd numeric(10, 6),
  retries int NOT NULL DEFAULT 0 CHECK (retries >= 0),
  files_changed int NOT NULL DEFAULT 0,
  gates_passed int NOT NULL DEFAULT 0,
  gates_failed int NOT NULL DEFAULT 0,
  first_try_success bool NOT NULL DEFAULT false,
  yash_override bool NOT NULL DEFAULT false,
  composite_score numeric(5, 2),
  output_summary text,
  error_log text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_agent_runs_agent_id_created ON agent_runs(agent_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_runs_classification ON agent_runs(classification);
CREATE INDEX IF NOT EXISTS idx_agent_runs_created_at ON agent_runs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_runs_composite_score ON agent_runs(composite_score DESC);

ALTER TABLE agent_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "agent_runs_service_role_all" ON agent_runs FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE agent_runs IS 'Every agent task execution. Central table for performance analysis. Witness writes here on every run.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS agent_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  review_date date NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  classification text NOT NULL CHECK (classification IN ('PROMOTE', 'SCALE', 'STEADY', 'TRAIN', 'PIP', 'RETIRE')),
  rationale text NOT NULL,
  peer_avg_score numeric(5, 2),
  agent_avg_score numeric(5, 2),
  decision_approved bool NOT NULL DEFAULT false,
  approved_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_agent_reviews_agent_period ON agent_reviews(agent_id, review_date DESC);
CREATE INDEX IF NOT EXISTS idx_agent_reviews_review_date ON agent_reviews(review_date DESC);

ALTER TABLE agent_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "agent_reviews_service_role_all" ON agent_reviews FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE agent_reviews IS 'Cadence weekly review record: PROMOTE | SCALE | STEADY | TRAIN | PIP | RETIRE.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS pip_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  opened_at timestamptz NOT NULL DEFAULT now(),
  deadline timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed')),
  reason text NOT NULL,
  metrics_at_open jsonb NOT NULL,
  metrics_at_close jsonb,
  outcome text CHECK (outcome IS NULL OR outcome IN ('resolved', 'demoted', 'retired')),
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_pip_records_agent_id ON pip_records(agent_id);
CREATE INDEX IF NOT EXISTS idx_pip_records_active ON pip_records(agent_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_pip_records_deadline ON pip_records(deadline);

ALTER TABLE pip_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "pip_records_service_role_all" ON pip_records FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE pip_records IS 'Performance Improvement Plans. 14-day duration, NO extensions. Outcome: resolved | demoted | retired.';

-- ============================================================================
-- TRAINING TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS training_cycles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cycle_id text NOT NULL UNIQUE,
  triggered_by text NOT NULL CHECK (triggered_by IN ('yash_correction', 'witness_antipattern', 'mira_lessons', 'cadence_request', 'forge_gap', 'trend_synthesis', 'weekly_batch')),
  trigger_priority text NOT NULL CHECK (trigger_priority IN ('P0', 'P1', 'P2', 'P3', 'P4', 'P5')),
  signals_consumed jsonb NOT NULL DEFAULT '{}'::jsonb,
  patch_count int NOT NULL DEFAULT 0,
  agents_affected text[] NOT NULL DEFAULT ARRAY[]::text[],
  changelog text,
  rollback_hash text,
  status text NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'staged_for_review', 'applied', 'rolled_back', 'completed')),
  applied_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_training_cycles_status ON training_cycles(status);
CREATE INDEX IF NOT EXISTS idx_training_cycles_applied_at ON training_cycles(applied_at DESC);
CREATE INDEX IF NOT EXISTS idx_training_cycles_agents_affected ON training_cycles USING GIN(agents_affected);

ALTER TABLE training_cycles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "training_cycles_service_role_all" ON training_cycles FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE training_cycles IS 'Tutor training runs. P0=Yash immediate, P1=Witness antipattern (1h), P2=Mira lessons (next day), P3-P5=weekly batch.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS training_patches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cycle_id uuid NOT NULL REFERENCES training_cycles(id) ON DELETE CASCADE,
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
