  section_target text NOT NULL,
  content_added text NOT NULL,
  rollback_content text NOT NULL,
  applied bool NOT NULL DEFAULT false,
  applied_at timestamptz,
  impact_score numeric(5, 2),
  measured_at timestamptz,
  rolled_back bool NOT NULL DEFAULT false,
  rolled_back_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_training_patches_cycle_id ON training_patches(cycle_id);
CREATE INDEX IF NOT EXISTS idx_training_patches_agent_id ON training_patches(agent_id);
CREATE INDEX IF NOT EXISTS idx_training_patches_applied ON training_patches(applied);

ALTER TABLE training_patches ENABLE ROW LEVEL SECURITY;
CREATE POLICY "training_patches_service_role_all" ON training_patches FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE training_patches IS 'Per-agent surgical patches. rollback_content REQUIRED — auto-rollback if impact_score < -10 (regression).';

-- ============================================================================

CREATE TABLE IF NOT EXISTS training_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  skill_gap text NOT NULL,
  priority text NOT NULL CHECK (priority IN ('P0', 'P1', 'P2', 'P3', 'P4', 'P5')),
  reviewed bool NOT NULL DEFAULT false,
  requested_by text NOT NULL,
  cycle_id uuid REFERENCES training_cycles(id) ON DELETE SET NULL,
  fulfilled bool NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_training_requests_agent_id ON training_requests(agent_id);
CREATE INDEX IF NOT EXISTS idx_training_requests_unfulfilled ON training_requests(fulfilled) WHERE fulfilled = false;

ALTER TABLE training_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "training_requests_service_role_all" ON training_requests FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE training_requests IS 'Cadence files training requests; Tutor batches and fulfills.';

-- ============================================================================
-- ANALYTICS TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS cost_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  model text NOT NULL,
  input_tokens int NOT NULL CHECK (input_tokens >= 0),
  output_tokens int NOT NULL CHECK (output_tokens >= 0),
  cost_usd numeric(10, 6) NOT NULL CHECK (cost_usd >= 0),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_cost_logs_run_id ON cost_logs(run_id);
CREATE INDEX IF NOT EXISTS idx_cost_logs_agent_id ON cost_logs(agent_id);
CREATE INDEX IF NOT EXISTS idx_cost_logs_model ON cost_logs(model);
CREATE INDEX IF NOT EXISTS idx_cost_logs_created_at ON cost_logs(created_at DESC);

ALTER TABLE cost_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "cost_logs_service_role_all" ON cost_logs FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE cost_logs IS 'Per-run token cost. Enables per-agent and per-pod cost trending.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS pattern_usage (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  pattern_file text NOT NULL,
  pattern_name text NOT NULL,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  outcome text CHECK (outcome IS NULL OR outcome IN ('helped', 'neutral', 'hurt')),
  used_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_pattern_usage_agent_id ON pattern_usage(agent_id);
CREATE INDEX IF NOT EXISTS idx_pattern_usage_pattern_file ON pattern_usage(pattern_file);
CREATE INDEX IF NOT EXISTS idx_pattern_usage_used_at ON pattern_usage(used_at DESC);

ALTER TABLE pattern_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY "pattern_usage_service_role_all" ON pattern_usage FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE pattern_usage IS 'Tracks pattern usage by agents. Used by Mira to detect knowledge decay (90 days unused → archive).';

-- ============================================================================

CREATE TABLE IF NOT EXISTS delegation_graph (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  from_agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  to_agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  task_type text NOT NULL,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  success bool NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_delegation_graph_from ON delegation_graph(from_agent_id);
CREATE INDEX IF NOT EXISTS idx_delegation_graph_to ON delegation_graph(to_agent_id);
CREATE INDEX IF NOT EXISTS idx_delegation_graph_success ON delegation_graph(success);

ALTER TABLE delegation_graph ENABLE ROW LEVEL SECURITY;
CREATE POLICY "delegation_graph_service_role_all" ON delegation_graph FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE delegation_graph IS 'Agent-to-agent task handoff. Used by Forge to detect bottlenecks (>40% delegation to one agent).';

-- ============================================================================
-- AUDIT & COMPLIANCE TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS incidents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  run_id uuid REFERENCES agent_runs(id) ON DELETE SET NULL,
  incident_type text NOT NULL CHECK (incident_type IN ('antipattern', 'regression', 'pip_candidate', 'promotion_candidate', 'production_bug', 'cost_breach', 'time_breach')),
  severity text NOT NULL CHECK (severity IN ('S1', 'S2', 'S3', 'S4')),
  description text NOT NULL,
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  root_cause text,
  resolved bool NOT NULL DEFAULT false,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_incidents_agent_id ON incidents(agent_id);
CREATE INDEX IF NOT EXISTS idx_incidents_severity ON incidents(severity);
CREATE INDEX IF NOT EXISTS idx_incidents_resolved ON incidents(resolved);
CREATE INDEX IF NOT EXISTS idx_incidents_type_severity ON incidents(incident_type, severity);

ALTER TABLE incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "incidents_service_role_all" ON incidents FOR ALL TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE incidents IS 'Witness writes incidents. S1=PIP candidate, S2=promotion candidate, S3=antipattern, S4=info.';

-- ============================================================================

CREATE TABLE IF NOT EXISTS memory_updates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  updated_by text NOT NULL,
  file_path text NOT NULL,
  change_type text NOT NULL CHECK (change_type IN ('create', 'update', 'delete', 'archive')),
  diff_summary text,
  bytes_changed int,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_memory_updates_updated_by ON memory_updates(updated_by);
CREATE INDEX IF NOT EXISTS idx_memory_updates_file_path ON memory_updates(file_path);
