CREATE OR REPLACE VIEW agent_leaderboard AS
SELECT
  a.id, a.name, a.title, a.level_title, a.department, a.pod, a.status,
  COALESCE((a.stats ->> 'run_count')::int, 0) as run_count,
  COALESCE((a.stats ->> 'success_rate')::numeric, 0) as success_rate,
  COALESCE((a.stats ->> 'avg_composite_score')::numeric, 0) as composite_score,
  COALESCE((a.stats ->> 'total_cost_usd')::numeric, 0) as total_cost_usd,
  (a.stats ->> 'last_run_at')::timestamptz as last_run_at,
  RANK() OVER (ORDER BY COALESCE((a.stats ->> 'avg_composite_score')::numeric, 0) DESC) as rank
FROM agents a
WHERE a.status IN ('deployed', 'training');

COMMENT ON VIEW agent_leaderboard IS 'Live leaderboard for Cadence weekly review.';

CREATE OR REPLACE VIEW recent_activity AS
SELECT
  ae.id, ae.agent_id, a.name as agent_name, ae.event_type, ae.payload,
  ar.run_id, ar.classification, ar.composite_score, ae.created_at
FROM agent_events ae
LEFT JOIN agents a ON ae.agent_id = a.id
LEFT JOIN agent_runs ar ON ae.run_id = ar.id
ORDER BY ae.created_at DESC
LIMIT 200;

COMMENT ON VIEW recent_activity IS 'Last 200 events across all agents — for Witness daily sweep + ad-hoc debug.';

CREATE OR REPLACE VIEW pod_health AS
SELECT
  COALESCE(pod, 'unassigned') as pod,
  COUNT(*) as agent_count,
  AVG(COALESCE((stats ->> 'avg_composite_score')::numeric, 0))::numeric(5, 2) as avg_pod_score,
  AVG(COALESCE((stats ->> 'success_rate')::numeric, 0))::numeric(5, 2) as avg_pod_success_rate,
  SUM(COALESCE((stats ->> 'total_cost_usd')::numeric, 0))::numeric(10, 2) as total_pod_cost
FROM agents
WHERE status IN ('deployed', 'training')
GROUP BY pod
ORDER BY avg_pod_score DESC;

COMMENT ON VIEW pod_health IS 'Per-pod health for stack-pod monitoring (Pod A, B, C). Used by Cadence + Rex.';

